#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=9

banner "mRoleScope 腾讯云远端开发环境"

stage "个人账号、MFA 与成本边界"
say "本向导不会读取或保存腾讯云账号、密码、支付方式、CVM 登录密钥、COS 密钥或 GitHub 令牌。"
open_url "https://console.cloud.tencent.com/"
step "登录你个人名下的腾讯云账号；确认不是公司账号、企业子账号、公司 VPN 或公司支付方式。"
step "在账号安全设置中启用 MFA，并确认你能完成一次 MFA 登录。"
step "准备月付预算：CVM、公共 IPv4/带宽和 COS 合计的续费月均不得高于 100 元。"
warn "不要购买 TencentDB、负载均衡、CDN、快照或数据库备份服务；它们不在本期范围。"
if ! confirm "已确认个人账号、MFA 和每月成本边界？"; then
  say "请先完成这一步；之后重新运行本向导。"
  return 1
fi

stage "上海 COS 桶与私有归档边界"
say "先创建私有 COS 桶，为后续成功采集批次的原始归档预留位置；本期不会上传真实招聘数据。"
open_url "https://www.tencentcloud.com/document/product/436/13309"
open_url "https://console.cloud.tencent.com/cos/bucket"
step "在 COS 控制台选择创建桶，地域选择上海；桶名使用仅你可识别的唯一名称，例如 mrolescope-archive-<个人后缀>。"
step "访问权限选择私有读写；不要启用静态网站托管、公共读或公共写。"
step "本期不要启用跨地域复制、版本控制、归档规则或公开 CDN；这些会增加成本或改变备份边界。"
note "桶名和地域是非秘密信息，但向导也不会将它们写进本机 .env 或 GitHub Variables。"
if ! confirm "已创建一个上海地域、私有访问的 COS 桶？"; then
  say "请保留此阶段，创建完成后重新运行本向导。"
  return 1
fi

stage "创建上海 CVM 与最小入站安全组"
say "CVM 是可替换的远端工作室：部署图纸在 Git，未来成功原始归档在 COS；它本身不是永久数据仓库。"
open_url "https://www.tencentcloud.com/document/product/213/2764"
open_url "https://console.cloud.tencent.com/cvm/instance/index"
step "在 CVM 控制台新建实例：地域上海、可用区按当天库存、Ubuntu 22.04 LTS x86_64、2 vCPU / 2 GiB、50 GiB 系统盘、月付。购买页的 1 Mbps 带宽可保留；首次镜像拉取较慢但本期无需加购。"
step "创建或选择独立 VPC/子网和安全组。入站默认拒绝：不要添加 5432、8080、80 或 443；优先不用 SSH。"
step "如确实需要 SSH 救援，才添加 TCP 22，来源只填你的固定个人公网 IP；绝不能填 0.0.0.0/0。"
step "保持到 GitHub、Docker Hub（经腾讯云官方镜像加速器）、系统更新和腾讯云服务的必要出站 HTTPS；公网 IPv4 仅供低成本出站连接，不代表开放公网服务。"
warn "购买会产生费用。请在支付前复核地域、月付周期、续费价、带宽与公共 IPv4 的账单。"
if ! confirm "已自行创建符合上述规格与安全组边界的 CVM？"; then
  say "尚未购买也没关系；不要继续后续主机配置。"
  return 1
fi

stage "通过受控运维通道建立主机基线"
say "优先从腾讯云 Workbench 或受控运维通道进入 CVM；不要把密码、私钥或实例登录信息粘贴回本向导。"
open_url "https://console.cloud.tencent.com/workbench"
step "以具备 sudo 权限的维护身份登录 CVM，依次运行以下命令："
say "sudo apt update"
say "sudo apt install -y docker.io docker-compose-v2 ca-certificates curl"
say "sudo systemctl enable --now docker"
say "sudo docker version"
say "sudo docker compose version"
step "为 2 GiB 内存主机创建一次性 2 GiB swap（逐行运行；已存在 /swapfile 时不要重复创建）："
say "sudo fallocate -l 2G /swapfile"
say "sudo chmod 600 /swapfile"
say "sudo mkswap /swapfile"
say "sudo swapon /swapfile"
say "echo '/swapfile none swap sw 0 0' | sudo tee -a /etc/fstab"
say "free -h"
step "创建最小运行目录与专用非登录部署身份："
say "sudo adduser --system --group --home /opt/mrolescope-runner mrolescope-deploy"
say "sudo install -d -o root -g root -m 0755 /opt/mrolescope /etc/mrolescope /var/lib/mrolescope"
say "sudo install -d -o root -g root -m 0700 /etc/mrolescope/secrets"
step "检查监听端口：sudo ss -ltn。此时不应有 PostgreSQL 5432 或项目 API 端口在公网监听。"
if ! confirm "Docker、Compose、2 GiB swap、目录和 mrolescope-deploy 身份均已就绪，且未开放数据库/API 入站端口？"; then
  say "请修复主机基线后重新运行本向导。"
  return 1
fi

stage "GitHub 主分支与部署 Environment"
say "这一阶段只建立发布权限边界，不输入数据库、COS 或 CVM 密钥。"
open_url "https://github.com/lf19910822/mRoleScope/settings"
step "进入 Settings → Rules（或 Branches）；为 main 创建保护规则：禁止删除和 force push，要求现有 CI 成功后才能合并。"
step "如果仓库/套餐提供部署分支或审核保护，限制部署仅来自 main，并将人工部署审核者设为你自己。"
open_url "https://github.com/lf19910822/mRoleScope/settings/environments"
step "创建名为 remote-development 的 Environment。不要在此处保存 PostgreSQL、COS 或 CVM 的长期密钥。"
note "若 GitHub 当前套餐未显示某项 Environment 保护控件，保留 Environment 名称；后续部署工作流仍会强制 main + 手动触发。"
if ! confirm "main 的保护与 remote-development Environment 已按可用功能配置？"; then
  say "请完成 GitHub 权限边界后再继续。"
  return 1
fi

stage "部署资产就绪检查"
say "接下来需要仓库中的远端 Compose 定义、Docker Hub 构建工作流、手动部署工作流和 root 受控部署入口。"
say "这些是项目代码工作，不应由你在 CVM 上手工复制或临时编写。"
required_deploy_assets=(
  ".github/workflows/remote-development-deploy.yml"
  "deploy/remote-development/compose.yaml"
  "deploy/remote-development/mrolescope-deploy"
  "deploy/remote-development/bootstrap.sh"
)
missing_deploy_assets=()
for deploy_asset in "${required_deploy_assets[@]}"; do
  [[ -f "$deploy_asset" ]] || missing_deploy_assets+=("$deploy_asset")
done
if (( ${#missing_deploy_assets[@]} )); then
  warn "这些部署资产尚未在当前工作树中生成；这是预期的安全暂停点。"
  note "缺少：${missing_deploy_assets[*]}"
  say "现在不要注册 runner、不要写运行时密码、不要部署本地源码到 CVM。"
  say "回到 Codex，要求完成“远端部署资产”实现；文件就绪后从本向导重新开始，前五阶段可安全确认通过。"
  return 2
fi
step "检测到完整的部署资产。审阅 workflow、Compose、root 部署入口与 bootstrap 脚本；镜像名、runner 标签和部署入口必须与本向导后续阶段一致。"
step "先在 Docker Hub 创建两个公开仓库：<你的 Docker Hub 用户名>/mrolescope-api 与 <你的 Docker Hub 用户名>/mrolescope-migrate。创建一个仅用于推送的最小权限 Docker Hub Token；它是秘密，不要粘贴到本向导或聊天。"
step "在 GitHub 仓库 Settings → Secrets and variables → Actions 添加：非秘密 Variable DOCKERHUB_USERNAME（小写 Docker Hub 用户名）和 Secret DOCKERHUB_TOKEN（刚创建的 Token）。"
step "将这些文件经正常审阅合入受保护 main。打开 main 的提交页面，复制这次合入后的完整 40 位 commit SHA；它像‘带封条的图纸版本号’，不是 main 分支名。"
step "在 CVM 上仅用该固定 SHA 安装部署边界。先下载 bootstrap："
say "curl --fail --location --proto '=https' --tlsv1.2 \"https://raw.githubusercontent.com/lf19910822/mRoleScope/<FULL_MAIN_COMMIT_SHA>/deploy/remote-development/bootstrap.sh\" --output /tmp/mrolescope-bootstrap.sh"
say "sudo bash /tmp/mrolescope-bootstrap.sh <FULL_MAIN_COMMIT_SHA> <DOCKERHUB_USERNAME>"
note "这一步只安装 root 所有的 Compose、受控部署入口、Docker Hub 命名空间配置和 sudoers 规则；不会下载业务源码、拉取应用镜像、启动容器或创建密码。"
if ! confirm "已确认部署资产已审阅、合并到受保护 main，并已用完整 SHA 成功运行 bootstrap？"; then
  return 1
fi

stage "注册专用 self-hosted runner"
say "runner 只接受本仓库受保护 main 的人工部署任务，并只向外连接 GitHub；不要为 GitHub Actions 打开 CVM 入站 SSH。"
open_url "https://docs.github.com/en/actions/how-tos/hosting-your-own-runners/managing-self-hosted-runners/adding-self-hosted-runners"
open_url "https://github.com/lf19910822/mRoleScope/settings/actions/runners"
step "在 GitHub 选择 New self-hosted runner → Linux → x64。以 mrolescope-deploy 身份进入临时 shell：sudo -u mrolescope-deploy -H /bin/bash；在其家目录执行页面展示的下载、校验、解压命令。"
step "注册令牌是短期敏感值：只粘贴到 CVM 终端的 config.sh 提示中；不要粘贴到本向导、Git、.env、GitHub Secrets 或聊天记录。"
step "运行页面展示的 ./config.sh 命令时，在末尾追加 --labels mrolescope-deploy；这相当于给这台专用投递车贴上唯一的‘部署专用’标签。"
step "退出临时 shell 后，使用页面展示的 svc.sh 命令将 runner 注册为 mrolescope-deploy 身份的 systemd 服务并启动。"
step "回到 GitHub runners 页面，确认该 runner 显示 Online；普通 CI 与 Pull Request 不能使用它。"
if ! confirm "专用 runner 已在线，且没有为此开放任何新的 CVM 入站端口？"; then
  return 1
fi

stage "写入 root-only 运行时凭据"
say "本阶段只在仓库部署资产已经明确变量格式后进行。向导不会要求、显示或保存任何密码。"
step "在 CVM 运行 sudoedit /etc/mrolescope/secrets/remote-development.env；只写入 POSTGRES_DB、POSTGRES_USER、POSTGRES_PASSWORD、DATABASE_URL 四项，具体模板见开发指导。"
step "密码在 CVM 本机用 openssl rand -hex 32 生成；不要把输出发给任何人。DATABASE_URL 中填入同一个密码，因为十六进制字符不需要 URL 转义。"
step "保存后运行：sudo chown root:root /etc/mrolescope/secrets/remote-development.env；再运行：sudo chmod 600 /etc/mrolescope/secrets/remote-development.env。"
step "暂时不要写 COS 身份：尚未实现归档上传。不要将数据库值配置为 GitHub Secret、Repository Variable 或镜像构建参数。"
warn "不要访问招聘官网，也不要给尚不存在的归档功能预置 COS 写权限。"
if ! confirm "运行时凭据只存在于 CVM 的 root-only 文件中，且没有出现在 GitHub 或本机？"; then
  return 1
fi

stage "首次离线部署与环境验收"
say "现在只验收远端开发环境；不启动同步定时器、不请求招聘官网、不形成正式采集批次。"
open_url "https://github.com/lf19910822/mRoleScope/actions"
step "在 Actions 中选择 remote-development 手动部署工作流，从 main 发起；确认它先运行测试，再构建并推送公开 Docker Hub 镜像，最后通过腾讯云官方镜像加速器在专用 runner 上部署固定 digest。"
step "通过受控运维通道在 CVM 本机检查：curl -fsS http://127.0.0.1:8080/healthz 和 curl -fsS http://127.0.0.1:8080/readyz。"
step "检查 docker compose ps、发布记录、运行镜像 digest 与工作流 Git SHA 一致；再用 sudo ss -ltn 确认 5432 和 API 没有公网监听。"
step "故意不创建调度器、不运行 worker 在线采集、不切换旧同步任务。验收通过后，环境才可作为后续数据后台开发基础。"
if ! confirm "离线部署、healthz、readyz、私网端口与镜像 digest 验收均已通过？"; then
  warn "不要启用任何同步任务；保留工作流和本机检查信息以便诊断。"
  return 1
fi

finish
}

run_wizard "$@"; exit
